export async function asyncMapLimit<T, U>(values: readonly T[], limit: number, fn: (value: T, index: number) => Promise<U>): Promise<U[]> {
  if (!Number.isInteger(limit) || limit <= 0) throw new RangeError("limit must be a positive integer");
  const result: U[] = new Array(values.length);
  let next = 0;
  let failed = false;
  async function worker(): Promise<void> {
    while (!failed && next < values.length) {
      const index = next++;
      try {
        result[index] = await fn(values[index], index);
      } catch (error) {
        failed = true;
        throw error;
      }
    }
  }
  await Promise.all(Array.from({length: Math.min(limit, values.length)}, () => worker()));
  return result;
}
